  "claims": [
    {
      "claim": "The query is a permanently charged quaternary pyridinium carbamate; the closest carbamate context, physostigmine, is reported to have poor oral bioavailability, supporting a low-F outcome.",
      "card_ids": ["C08"]
    },
    {
      "claim": "A charged, polar small-molecule context, BMS-187745, had an absolute oral bioavailability of 2.6% in humans, indicating that permanent charge/polarity can drive F well below 20%.",
      "card_ids": ["C09"]
    },
    {
      "claim": "Multiple related low-F contexts remain below 20%: tilidine ~3-7.6% systemic/absolute availability, agomelatine <5%, apocynin <10% in humans and 2.8-8.3% in rats, and aniracetam 8.6-11.4% in rats.",
      "card_ids": ["C01", "C07", "C02", "C20", "C23", "C19", "C26"]
    },
    {
      "claim": "New L2 records add direct low absolute/systemic F values (tilidine 7.6±5.3%, apocynin 2.8% and 8.3%, aniracetam 11.4% and 8.6%, agomelatine <5%), reinforcing the low direction.",
      "card_ids": ["C18", "C20", "C23", "C19", "C26", "C17"]
    },
    {
      "claim": "The only near-threshold L2 value, methyl parathion ~20% in rats, is species- and dose-specific and does not outweigh the human <1.7% L1 value or the query's quaternary charge.",
      "card_ids": ["C21", "C04"]
    }
  ],
  "new_evidence_assessment": [
